async function scanBundle(input, deliver) {
  let delivered = 0;
  let lineNumber = 1;
  let pending = "";

  const processLine = async (line) => {
    if (line.endsWith("\r")) line = line.slice(0, -1);
    if (line.trim() === "") return true;

    let value;
    try {
      value = JSON.parse(line);
    } catch {
      const error = new Error(`Invalid JSON on line ${lineNumber}`);
      error.code = "BAD_LINE";
      error.line = lineNumber;
      throw error;
    }

    const result = await deliver(value, lineNumber);
    delivered++;
    return result !== false;
  };

  try {
    const decoder = new TextDecoder("utf-8");

    while (true) {
      const chunk = await input.read();

      if (chunk === null) {
        pending += decoder.decode();

        if (pending.length > 0) {
          const shouldContinue = await processLine(pending);
          if (!shouldContinue) return delivered;
        }

        return delivered;
      }

      pending += decoder.decode(chunk, { stream: true });

      let newlineIndex;
      while ((newlineIndex = pending.indexOf("\n")) !== -1) {
        const line = pending.slice(0, newlineIndex);
        pending = pending.slice(newlineIndex + 1);

        const shouldContinue = await processLine(line);
        lineNumber++;

        if (!shouldContinue) return delivered;
      }
    }
  } finally {
    await input.close();
  }
}
